def process(cleanBostonHarborSamples) -> pd.DataFrame:
    import pandas as pd

    df = cleanBostonHarborSamples.copy()

    # Swimming standard: Enterococcus <= 104 counts/100mL
    failed = df[df['enterococcus'] > 104].copy()

    # Exclude rows without an Enterococcus measurement (cannot evaluate failure)
    failed = failed[failed['enterococcus'].notna()]

    if len(failed) == 0:
        pct = 0.0
    else:
        pct = 100.0 * failed['rainWithin24h'].mean()

    return pd.DataFrame([{
        'failedSamples': int(len(failed)),
        'failedWithRainWithin24h': int(failed['rainWithin24h'].sum()),
        'percentage': round(pct, 2),
    }])
